import { useState, useRef } from 'react';
import {
  FileText,
  Upload,
  Download,
  Trash2,
  RefreshCw,
  Eye,
  AlertCircle,
  CheckCircle2,
  XCircle,
  BookOpen,
} from 'lucide-react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { useCatalogPDF } from '@/hooks/useCatalogPDF';
import { format } from 'date-fns';
import { toast } from 'sonner';
import PDFViewer from '@/components/PDFViewer';
import { UniversalLink } from '@lark-apaas/client-toolkit-lite';
import { useI18n } from '@/i18n/I18nContext';
import PageBreadcrumb from '@/components/PageBreadcrumb';

const MAX_SIZE_MB = 50;

export default function AdminCatalogPage() {
  const { adminT } = useI18n();
  const { pdfInfo, loading, saving, uploadPDF, resetToDefault, defaultPdfName } = useCatalogPDF();
  const [dragOver, setDragOver] = useState(false);
  const [resetOpen, setResetOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileSelect = async (file: File | undefined | null) => {
    if (!file) return;

    // 类型校验
    if (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf')) {
      toast.error('文件类型错误：仅支持 PDF 文件');
      return;
    }

    // 大小校验
    if (file.size > MAX_SIZE_MB * 1024 * 1024) {
      toast.error(`文件过大：最大支持 ${MAX_SIZE_MB}MB，当前文件 ${(file.size / 1024 / 1024).toFixed(1)}MB`);
      return;
    }

    const ok = await uploadPDF(file);
    if (ok) {
      toast.success('产品目录已更新');
    } else {
      toast.error('上传失败，请稍后重试');
    }
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setDragOver(false);
    const file = e.dataTransfer.files?.[0];
    handleFileSelect(file);
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setDragOver(true);
  };

  const handleDragLeave = () => {
    setDragOver(false);
  };

  const handleReset = async () => {
    const ok = await resetToDefault();
    if (ok) {
      toast.success('已恢复为默认产品目录');
    } else {
      toast.error('操作失败');
    }
    setResetOpen(false);
  };

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '-';
    return `${(bytes / 1024 / 1024).toFixed(2)} MB`;
  };

  return (
    <div className="space-y-6">
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[{ label: adminT('admin.catalog') }]}
      />
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-foreground flex items-center gap-2">
            <FileText className="size-6 text-primary" />
            产品目录管理
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            上传和管理产品目录 PDF，前台 About Us 页面展示
          </p>
        </div>
        <Badge variant="outline" className={pdfInfo.isCustom ? 'bg-success/15 text-success border-success/30' : 'bg-muted/50'}>
          {pdfInfo.isCustom ? <CheckCircle2 className="size-3 mr-1" /> : <AlertCircle className="size-3 mr-1" />}
          {pdfInfo.isCustom ? '已自定义' : '使用默认'}
        </Badge>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* 左侧：信息 + 上传 */}
        <div className="lg:col-span-1 space-y-6">
          {/* 当前 PDF 信息 */}
          <Card className="border-border/40 bg-card">
            <CardHeader>
              <CardTitle className="text-base">当前产品目录</CardTitle>
              <CardDescription>前台 About Us 页面展示的 PDF</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              {loading ? (
                <div className="flex items-center justify-center py-8">
                  <RefreshCw className="size-5 text-muted-foreground animate-spin" />
                </div>
              ) : (
                <>
                  <div className="flex items-start gap-3 p-3 rounded-lg bg-muted/30 border border-border/40">
                    <div className="size-10 shrink-0 rounded-md bg-primary/10 flex items-center justify-center">
                      <FileText className="size-5 text-primary" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="text-sm font-medium text-foreground truncate" title={pdfInfo.name}>
                        {pdfInfo.name}
                      </div>
                      <div className="text-xs text-muted-foreground mt-0.5">
                        {formatSize(pdfInfo.size)}
                      </div>
                      {pdfInfo.isCustom && pdfInfo.uploadDate && (
                        <div className="text-xs text-muted-foreground mt-0.5">
                          上传时间：{format(pdfInfo.uploadDate, 'yyyy-MM-dd HH:mm')}
                        </div>
                      )}
                      {!pdfInfo.isCustom && (
                        <div className="text-xs text-muted-foreground mt-0.5">
                          来源：默认内置
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="flex flex-col gap-2">
                    <Button variant="outline" size="sm" asChild>
                      <UniversalLink to={pdfInfo.url} target="_blank" rel="noopener noreferrer">
                        <Eye className="size-4 mr-1.5" />
                        预览 PDF
                      </UniversalLink>
                    </Button>
                    <Button variant="outline" size="sm" asChild>
                      <UniversalLink to={pdfInfo.url} download={pdfInfo.name}>
                        <Download className="size-4 mr-1.5" />
                        下载 PDF
                      </UniversalLink>
                    </Button>
                    {pdfInfo.isCustom && (
                      <Button
                        variant="outline"
                        size="sm"
                        className="text-destructive hover:text-destructive hover:bg-destructive/10 border-destructive/30"
                        onClick={() => setResetOpen(true)}
                      >
                        <Trash2 className="size-4 mr-1.5" />
                        删除并恢复默认
                      </Button>
                    )}
                  </div>
                </>
              )}
            </CardContent>
          </Card>

          {/* 上传区域 */}
          <Card className="border-border/40 bg-card">
            <CardHeader>
              <CardTitle className="text-base">上传新 PDF</CardTitle>
              <CardDescription>
                支持 PDF 格式，最大 {MAX_SIZE_MB}MB
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div
                onDrop={handleDrop}
                onDragOver={handleDragOver}
                onDragLeave={handleDragLeave}
                className={`relative border-2 border-dashed rounded-lg p-6 text-center transition-colors cursor-pointer ${
                  dragOver
                    ? 'border-primary bg-primary/5'
                    : 'border-border/60 hover:border-primary/50 hover:bg-muted/30'
                }`}
                onClick={() => fileInputRef.current?.click()}
              >
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="application/pdf,.pdf"
                  className="hidden"
                  onChange={(e) => handleFileSelect(e.target.files?.[0])}
                  disabled={saving}
                />
                <div className="size-12 mx-auto mb-3 rounded-full bg-primary/10 flex items-center justify-center">
                  {saving ? (
                    <RefreshCw className="size-6 text-primary animate-spin" />
                  ) : (
                    <Upload className="size-6 text-primary" />
                  )}
                </div>
                <p className="text-sm font-medium text-foreground mb-1">
                  {saving ? '上传中...' : '拖拽 PDF 到此处，或点击选择文件'}
                </p>
                <p className="text-xs text-muted-foreground">
                  PDF 格式 · 最大 {MAX_SIZE_MB}MB
                </p>
              </div>

              <div className="mt-3 flex items-start gap-2 text-xs text-muted-foreground">
                <AlertCircle className="size-3 mt-0.5 shrink-0 text-warning" />
                <span>
                  上传的 PDF 保存在浏览器 IndexedDB 中，仅当前浏览器可访问。
                  如需所有访客都看到，请将 PDF 文件放入网站的 <code className="bg-muted px-1 rounded">files/</code> 目录。
                </span>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* 右侧：PDF 预览 */}
        <div className="lg:col-span-2">
          <Card className="border-border/40 bg-card h-full flex flex-col">
            <CardHeader className="flex flex-row items-center justify-between">
              <div>
                <CardTitle className="text-base">PDF 预览</CardTitle>
                <CardDescription>
                  与前台 About Us 页面显示效果一致
                </CardDescription>
              </div>
              <Button variant="outline" size="sm" asChild>
                <UniversalLink to={pdfInfo.url} target="_blank" rel="noopener noreferrer">
                  <BookOpen className="size-4 mr-1.5" />
                  新窗口打开
                </UniversalLink>
              </Button>
            </CardHeader>
            <CardContent className="p-0 flex-1">
              <PDFViewer
                pdfUrl={pdfInfo.url}
                fileName={pdfInfo.name}
                minHeight="500px"
                maxHeight="600px"
              />
            </CardContent>
          </Card>
        </div>
      </div>

      {/* 重置确认 */}
      <AlertDialog open={resetOpen} onOpenChange={setResetOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>确认删除自定义 PDF？</AlertDialogTitle>
            <AlertDialogDescription>
              删除后将恢复为默认的 {defaultPdfName}，前台 About Us 页面也会同步显示默认目录。此操作无法撤销。
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>取消</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive hover:bg-destructive/90 text-destructive-foreground"
              onClick={handleReset}
            >
              确认删除
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
